import { defineOnceTool } from "agevex";
import type { FunctionReference } from "convex/server";
import { z } from "zod";

export const GOAL_LIMITS = { minChars: 1, goalChars: 4000 } as const;
export const goalText = z.string().trim().min(GOAL_LIMITS.minChars).max(GOAL_LIMITS.goalChars);
// Core validates every ToolContext fact (nonempty, at most LIMITS.factBytes
// UTF-8 bytes) before a tool runs, so the scope is passed through unchanged.
type Scope = { subject: string; threadId: string; runId: string };
export type GoalFunctions = {
  check: FunctionReference<"query", "internal", Scope, { goal: string | null }>;
  set: FunctionReference<"mutation", "internal", Scope & { goal: string }, { goal: string }>;
};

/** One explicit goal per owner, thread and user run; checking reads it back. */
export function createGoalTools(refs: GoalFunctions) {
  const tools = {
    goal_set: defineOnceTool({
      name: "goal_set",
      input: z.strictObject({ goal: goalText }),
      run: async (input, tc) => {
        tc.signal.throwIfAborted();
        // `input` was validated by AI SDK; ownership comes from ToolContext only.
        return tc.ctx.runMutation(refs.set, {
          subject: tc.subject,
          threadId: tc.threadId,
          runId: tc.runId,
          goal: input.goal,
        });
      },
    }),
    goal_check: defineOnceTool({
      name: "goal_check",
      input: z.strictObject({}),
      run: async (_input, tc) => {
        tc.signal.throwIfAborted();
        return tc.ctx.runQuery(refs.check, {
          subject: tc.subject,
          threadId: tc.threadId,
          runId: tc.runId,
        });
      },
    }),
  };
  tools.goal_set.description =
    "Set the explicit goal for this owner's current thread and user run. Report progress against this goal.";
  tools.goal_check.description =
    "Read this run's goal, or null when unset. Assess your work against it; this tool does not independently verify success.";
  return tools;
}

import { defineSchema, defineTable, type DataModelFromSchemaDefinition } from "convex/server";
import { v } from "convex/values";

/**
 * Merge into the host schema; each field is used by goal_set/goal_check.
 * Native thread metadata has no custom field for a run goal. See
 * @convex-dev/agent/src/client/threads.ts:18-30,55-63 (version 0.7.7).
 */
export const goalTables = {
  agevexGoals: defineTable({
    subject: v.string(),
    threadId: v.string(),
    runId: v.string(),
    goal: v.string(),
  }).index("by_owner_thread_run", ["subject", "threadId", "runId"]),
};
const schema = defineSchema(goalTables);
export type GoalDataModel = DataModelFromSchemaDefinition<typeof schema>;

import {
  internalMutationGeneric,
  internalQueryGeneric,
  type MutationBuilder,
  type QueryBuilder,
} from "convex/server";
import { v } from "convex/values";
import { goalText } from "./goals.js";
import type { GoalDataModel } from "./goalsSchema.js";

const query = internalQueryGeneric as QueryBuilder<GoalDataModel, "internal">;
const mutation = internalMutationGeneric as MutationBuilder<GoalDataModel, "internal">;
const scope = { subject: v.string(), threadId: v.string(), runId: v.string() };

export const check = query({
  args: scope,
  returns: v.object({ goal: v.union(v.string(), v.null()) }),
  handler: async (ctx, args) => {
    // subject/threadId/runId are core-validated facts (<= LIMITS.factBytes =
    // 128 UTF-8 bytes each). One row: 4000 × 4 goal bytes + 3 × 128 scope bytes
    // + 1 KiB overhead < 18 KiB. unique() takes at most TWO rows then rejects
    // duplicates (convex/src/server/impl/query_impl.ts:334-343): < 36 KiB,
    // two docs and one query. Even two host-corrupted 1 MiB rows fit 16 MiB.
    // No history scan, model call, copied request content or native transcript.
    const row = await ctx.db
      .query("agevexGoals")
      .withIndex("by_owner_thread_run", (q) =>
        q.eq("subject", args.subject).eq("threadId", args.threadId).eq("runId", args.runId),
      )
      .unique();
    return { goal: row ? goalText.parse(row.goal) : null };
  },
});

export const set = mutation({
  args: { ...scope, goal: v.string() },
  returns: v.object({ goal: v.string() }),
  handler: async (ctx, args) => {
    const owner = { subject: args.subject, threadId: args.threadId, runId: args.runId };
    // The trimmed 1-4000 character bound is not a Convex validator, so re-check
    // it at the data boundary.
    const goal = goalText.parse(args.goal);
    // Same < 36 KiB / two-document read as check, one < 18 KiB write and one query. The
    // transaction's index read serializes concurrent first writes for this run.
    const row = await ctx.db
      .query("agevexGoals")
      .withIndex("by_owner_thread_run", (q) =>
        q.eq("subject", owner.subject).eq("threadId", owner.threadId).eq("runId", owner.runId),
      )
      .unique();
    if (row) await ctx.db.patch("agevexGoals", row._id, { goal });
    else await ctx.db.insert("agevexGoals", { ...owner, goal });
    return { goal };
  },
});
